css:
.crmseo{--crmseo-paper:#fff;--crmseo-ink:#111;--crmseo-text:#333;--crmseo-accent:#1f5fbf;--crmseo-accent-text:#fff;--crmseo-dark:#141a20;--crmseo-darker:#0c1014;--crmseo-line:#e3e6ea;--crmseo-muted:#5f6b75;--crmseo-soft:#f4f6f8;--crmseo-font:inherit;--crmseo-heading-font:inherit;--crmseo-case:none;--crmseo-radius:8px;--crmseo-width:1180px;
 font-family:var(--crmseo-font);color:var(--crmseo-text);background:var(--crmseo-paper);line-height:1.6;overflow-wrap:anywhere}
.crmseo *{box-sizing:border-box}
.crmseo-w{max-width:var(--crmseo-width);margin:0 auto;padding:0 20px}
.crmseo-b{padding:64px 0}
.crmseo-t-soft{background:var(--crmseo-soft)}
.crmseo-t-dark{background:var(--crmseo-dark);color:#d6dbe0}
.crmseo :is(h1,h2,h3,h4){font-family:var(--crmseo-heading-font);color:var(--crmseo-ink);text-transform:var(--crmseo-case);line-height:1.15;margin:0 0 .5em}
.crmseo .crmseo-t-dark :is(h1,h2,h3,h4),.crmseo .crmseo-hero h1{color:#fff}
.crmseo.crmseo-links{background:none}
.crmseo h1{font-size:clamp(32px,5vw,56px)}.crmseo h2{font-size:clamp(24px,3vw,36px)}.crmseo h3{font-size:19px}
.crmseo p{margin:0 0 1em}.crmseo a{color:inherit}
.crmseo-kicker,.crmseo-eyebrow{display:inline-block;margin-bottom:10px;font-size:12px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--crmseo-accent)}
.crmseo-hero{padding:96px 0 80px;background:var(--crmseo-darker);color:#e8ecef}
.crmseo-hero--img{background:linear-gradient(90deg,rgba(0,0,0,.78),rgba(0,0,0,.35)),var(--crmseo-hero-img) center/cover no-repeat}
.crmseo-hero h1{max-width:900px}.crmseo-lead{max-width:720px;font-size:19px}
.crmseo-k-hero{padding:0}
.crmseo-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:24px}
.crmseo-btn{display:inline-block;padding:13px 22px;border-radius:var(--crmseo-radius);background:var(--crmseo-accent);color:var(--crmseo-accent-text)!important;font-weight:700;text-decoration:none}
.crmseo-btn--ghost{background:transparent;color:inherit!important;border:1px solid currentColor}
.crmseo-two{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.3fr);gap:48px;align-items:start}
.crmseo-two--rev>div:first-child{order:2}.crmseo-two--text{grid-template-columns:1fr;max-width:860px}
.crmseo-img{width:100%;height:auto;border-radius:var(--crmseo-radius);display:block}
.crmseo-facts{display:grid;gap:10px;margin:20px 0 0}.crmseo-facts div{display:flex;gap:12px;border-top:1px solid var(--crmseo-line);padding-top:10px}
.crmseo-facts dt{font-weight:700;min-width:110px}.crmseo-facts dd{margin:0}
.crmseo-grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}
.crmseo-grid3 article,.crmseo-pros>div{padding:24px;border:1px solid var(--crmseo-line);border-radius:var(--crmseo-radius);background:var(--crmseo-paper)}
.crmseo-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:18px;margin-top:20px}
.crmseo-card{display:flex;flex-direction:column;border:1px solid var(--crmseo-line);border-radius:var(--crmseo-radius);background:var(--crmseo-paper);color:var(--crmseo-text);text-decoration:none;overflow:hidden}
a.crmseo-card:hover{border-color:var(--crmseo-accent)}
.crmseo-card-img{width:100%;aspect-ratio:4/3;object-fit:cover;display:block}
.crmseo-card-body{display:flex;flex-direction:column;flex:1;padding:18px}.crmseo-card-body p{font-size:15px}
.crmseo-card small{font-weight:700;color:var(--crmseo-muted)}
.crmseo-more{margin-top:auto;padding-top:10px;font-size:13px;color:var(--crmseo-accent)}
.crmseo-num{display:block;font-weight:800;color:var(--crmseo-accent);margin-bottom:6px}
.crmseo-tag{display:inline-block;margin-bottom:8px;font-size:12px;font-weight:700;text-transform:uppercase;color:var(--crmseo-muted)}
.crmseo-chips{display:flex;flex-wrap:wrap;gap:8px}.crmseo-chips span{padding:6px 12px;border:1px solid var(--crmseo-line);border-radius:999px;font-size:14px}
.crmseo-chips--big span{font-size:16px;padding:8px 16px}
.crmseo-sections{display:grid;gap:40px}.crmseo-sections article{display:grid;grid-template-columns:60px minmax(0,1fr);gap:20px}
.crmseo :is(.crmseo-ticks,.crmseo-points,.crmseo-checks,.crmseo-cross){list-style:none;padding:0;margin:0 0 1em}
.crmseo :is(.crmseo-ticks,.crmseo-points,.crmseo-checks,.crmseo-cross) li{position:relative;padding:4px 0 4px 28px}
.crmseo :is(.crmseo-ticks,.crmseo-points,.crmseo-checks) li:before{content:"✓";position:absolute;left:0;font-weight:800;color:var(--crmseo-accent)}
.crmseo .crmseo-cross li:before{content:"✕";position:absolute;left:0;font-weight:800;color:#b3261e}
.crmseo-cols{columns:2;column-gap:40px}
.crmseo-table{overflow-x:auto}.crmseo-table table{width:100%;border-collapse:collapse;min-width:560px}
.crmseo-table :is(th,td){padding:12px 14px;border-bottom:1px solid var(--crmseo-line);text-align:left;vertical-align:top}
.crmseo-table th{background:var(--crmseo-soft);color:var(--crmseo-ink)}
.crmseo-pros{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}
.crmseo-faq details{border-bottom:1px solid var(--crmseo-line);padding:14px 0}
.crmseo-faq summary{cursor:pointer;font-weight:700;color:var(--crmseo-ink);list-style-position:outside}
.crmseo-t-dark .crmseo-faq summary{color:#fff}
.crmseo-faq details>div{padding-top:10px}
.crmseo-cta{text-align:center;max-width:860px}.crmseo-cta .crmseo-actions{justify-content:center}
.crmseo-shortcode{max-width:640px;margin:24px auto 0;text-align:left}
@media (max-width:860px){.crmseo-b{padding:44px 0}.crmseo-two,.crmseo-grid3,.crmseo-pros{grid-template-columns:1fr;gap:24px}.crmseo-two--rev>div:first-child{order:0}.crmseo-cols{columns:1}.crmseo-hero{padding:64px 0 52px}.crmseo-sections article{grid-template-columns:1fr;gap:4px}}
